        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Arm A (Control arm): Standard of Care (SoC) alone",
              "type": "ACTIVE_COMPARATOR",
              "description": "The SoC is defined as one the following treatment which was initiated 6 to 8 months ahead of inclusion in this trial and still ongoing at the time of the randomization and continued at least until the CRPC stage is reached.:\n\n* ADT with an ARSI (i.e. abiraterone + prednisone, or apalutamide, or enzalutamide) ± radiotherapyª\n* ADT with docetaxelᵇ plus an ARSI (i.e. abiraterone + prednisone, or darolutamide,) ± radiotherapyª\n\nª Radiotherapy can be part of any standard treatment aforementioned as long as it is not PSMA-based and completed at least 4 weeks ahead of randomization OR planned right after randomization in arm A.\n\nᵇ Whenever docetaxel was part of the systemic treatment initiation, its administration must have been completed at least 4 weeks ahead of randomization.",
              "interventionNames": [
                "Drug: Standard of Care"
              ]
            },
            {
              "label": "Arm B (Experimental arm): 177Lu-PMSA-617 + SoC",
              "type": "EXPERIMENTAL",
              "description": "Once every 6 weeks, 7400 MBq 177Lu-PMSA-617 will be administered for up to a total of 4 cycles. Upon 177Lu-PMSA-617 treatment completion, the ongoing standard systemic treatment is to be maintained and continued at least until the CRPC stage is reached.\n\nThe SoC is defined as one the following treatment which was initiated 6 to 8 months ahead of inclusion in this trial and still ongoing at the time of the randomization:\n\n* ADT with an ARSI (i.e. abiraterone + prednisone, or apalutamide, or enzalutamide) ± radiotherapyª\n* ADT with docetaxelᵇ plus an ARSI (i.e. abiraterone + prednisone, or darolutamide,) ± radiotherapyª\n\nª Radiotherapy can be part of any standard treatment aforementioned as long as it is not PSMA-based completed at least 4 weeks ahead of randomization OR planned right after 177Lu-PSMA-617 in arm B.\n\nᵇ Whenever docetaxel was part of the systemic treatment initiation, its administration must have been completed at least 4 weeks ahead of randomization.",
              "interventionNames": [
                "Drug: 177Lu-PMSA-617",
                "Drug: Standard of Care"
              ]
            }
          ],
          "interventions": [
            {
              "type": "DRUG",
              "name": "177Lu-PMSA-617",
