          "primaryOutcomes": [
            {
              "measure": "Overall survival (OS)",
              "description": "Overall survival (OS) is defined as the time from the date of randomization to the date of death due to any cause.",
              "timeFrame": "From randomization to death due to any cause, up to 8.5 years"
            },
            {
              "measure": "Radiographic progression-free survival (rPFS)",
              "description": "Radiographic progression-free survival (rPFS) is defined as the time from randomization to the date of radiographic progression according to PCWG3 criteria by investigator assessment, or death, whichever occurs first.",
              "timeFrame": "From randomization to radiographic progression or death, up to 8.5 years"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Castration-Resistance Prostate Cancer-Free Survival (CRPC-FS)",
              "description": "Castration-Resistance Prostate Cancer-Free Survival (CRPC-FS) is defined as the time from randomization to the onset of castration-resistance or death from any cause, whichever occurs first.",
              "timeFrame": "From randomization to onset of castration-resistance or death, up to 8.5 years"
            },
            {
              "measure": "Prostate Cancer-Specific Survival (PCSS)",
              "description": "Prostate Cancer-Specific Survival (PCSS) is defined as the time from the date of randomization to the date of death due to prostate cancer.",
              "timeFrame": "From the date of randomization to a PCSS event, up to 8.5 years"
            },
            {
              "measure": "PSA response",
              "description": "PSA response will be assessed by the maximum change of PSA (rise or fall) from baseline over the treatment period. A complete PSA response is defined by an undetectable level of serum PSA.",
              "timeFrame": "From baseline over the treatment period, up to 8.5 years"
            },
            {
              "measure": "Skeletal-related event-free survival (SRE-FS)",
              "description": "Skeletal-related event-free survival (SRE-FS) is defined as the time from the randomization date to the date of diagnosis of either a skeletal-related event (SRE) (fracture, or bone pain requiring radiation therapy, or spinal cord compression, or preventive surgery to the bones) or death, whichever occurs first.",
              "timeFrame": "From randomization to the onset of a SRE-FS event, up to 8.5 years"
            },
            {
              "measure": "Time to severe urinary event (SUE)",
              "description": "Time to severe urinary event (SUE) is defined as the time from the randomization date to the date of diagnosis of either one of the following SUE, whichever occurs first: urinary retention with need for a urinary catheter, suprapubic catheter, double J stent, nephrostomy, treatment of the prostate by radiotherapy or trans-urethral resection of the prostate (TURP) or prostatectomy done to relieve patients with local symptoms.",
              "timeFrame": "From randomization to the onset of a SUE event, up to 8.5 years"
            },
