          ],
          "secondaryOutcomes": [
            {
              "measure": "Radiological progression free survival defined as the duration between the start date of treatment and the date of the first progression of the disease according to criteria RECIST V1.1 and criteria PCWG3; or the date of death whatever the cause.",
              "description": "Correlation between biomarker(s) (molecular abnormalities retained on primary tumor sample for the first outcome measure) and survival without radiological progression",
              "timeFrame": "From enrollment to 24 months after Lu-PSMA treatment"
            },
            {
              "measure": "Biological progression free survival defined as the duration between the start date of treatment and the date of the first PSA progression",
              "description": "Correlation between biomarker(s) (molecular abnormalities retained on primary tumor sample for the first outcome measure) and survival without biological progression",
              "timeFrame": "From enrollment to 24 months after Lu-PSMA treatment"
            },
            {
              "measure": "Clinical progression free survival, definieds as the duration between the treatment start date and the date of the first clinical progression",
              "description": "Correlation between biomarker(s) (molecular abnormalities retained on primary tumor sample for the first outcome measure) and survival without clinical progression",
              "timeFrame": "From enrollment to 24 months after Lu-PSMA treatment"
            },
            {
              "measure": "Overall survival definied as the time interval between the start date of treatment and the date of death whatever the cause",
              "description": "Correlation between biomarker(s) (molecular abnormalities retained on primary tumor sample for the first outcome measure) and overall survival",
              "timeFrame": "From enrollement to the end of the study, up to 58 months"
            },
            {
              "measure": "Toxicities related to treatment of grade 3 or higher according to CTCAE v. 5.0 and any EIG",
              "description": "Correlation between the biomarker(s) (molecular abnormalities retained on primary tumor sample for the first outcome measure) and adverse effects during treatment.",
              "timeFrame": "From enrollment to the end of Lu-PSMA treatment, up to 58 months"
            },
            {
              "measure": "Performance status (0 to 4), pain and adverse events evaluations as assessed by CTCAE v4.0",
